export function victoryTier(score){const n=Math.max(0,Number(score)||0);return n<1e6?'black':n<2e6?'red':n<3e6?'green':n<4e6?'purple':n<5e6?'orange':'blue'}
export function victoriesView(rows,{esc,fmt}){return `<section class="victory-section"><h2>Galibiyetler</h2><p class="subtle">Her kutu kazanılan bir turdur. Skoru görmek için üzerine gel, klavyeyle seç veya dokun.</p><div class="victory-legend">${[['black','1 milyon altı'],['red','1–2 milyon'],['green','2–3 milyon'],['purple','3–4 milyon'],['orange','4–5 milyon'],['blue','5 milyon ve üstü']].map(([c,t])=>`<span><i class="victory-${c}"></i>${t}</span>`).join('')}</div>${rows.length?`<div class="victory-grid">${rows.map(r=>{const detail=r.room+' · '+fmt(r.score)+' skor · '+new Date(r.at).toLocaleString('tr-TR');return `<button type="button" class="victory-badge victory-${victoryTier(r.score)}" data-victory="${esc(detail)}" aria-label="${esc(detail)}" title="${esc(detail)}"><b>${esc(r.room)}</b><span class="victory-tooltip">${fmt(r.score)} skor<small>${esc(new Date(r.at).toLocaleDateString('tr-TR'))}</small></span></button>`}).join('')}</div>`:'<p class="notice">Henüz kaydedilmiş galibiyet yok.</p>'}<p id="victory-detail" class="victory-detail" role="status" aria-live="polite">Bir galibiyet seç.</p></section>`}
